// Family tree (ownership_answers.v2) editing for the seller AI.
// The document request is generated by our rules engine FROM this tree, so a
// wrong name or a missing relative is fixed here and the checklist re-syncs —
// never patched separately on the request, which would leave conflicting info.

type Json = Record<string, any>;

const PEOPLE_LISTS = ["deed", "kids", "sibs", "parents"] as const;
const ST = new Set(["living", "deceased"]);
const clean = (s: unknown) => String(s ?? "").trim();

/** True when the tree has deed holders who all have a name and a living/deceased answer. */
export function isUsableTree(v2: unknown): v2 is Json {
  const s = v2 as Json | undefined;
  if (!s || typeof s !== "object" || !Array.isArray(s.deed)) return false;
  const named = s.deed.filter((d: Json) => clean(d?.n));
  return named.length > 0 && named.every((d: Json) => ST.has(d.st));
}

/**
 * Checks an AI-proposed replacement tree. Returns the cleaned tree or an error.
 * Keeps keys the AI must not touch (contacts, submitted, signerCheck) from the
 * current tree unless it deliberately sent them.
 */
export function validateTreeEdit(current: unknown, proposed: unknown): { tree: Json } | { error: string } {
  if (!proposed || typeof proposed !== "object" || Array.isArray(proposed)) return { error: "No family tree sent" };
  const raw = JSON.stringify(proposed);
  if (raw.length > 30000) return { error: "Family tree too large" };
  const cur = (current && typeof current === "object" ? current : {}) as Json;
  const next: Json = { ...cur, ...(proposed as Json) };
  for (const k of ["contacts", "submitted", "signerCheck"]) if (!(k in (proposed as Json)) && k in cur) next[k] = cur[k];
  for (const list of PEOPLE_LISTS) {
    if (next[list] == null) continue;
    if (!Array.isArray(next[list])) return { error: `${list} must be a list` };
    for (const p of next[list]) {
      if (!p || typeof p !== "object" || !clean(p.id) || !clean(p.n)) return { error: `Every person in ${list} needs an id and a name` };
      if (p.st != null && !ST.has(p.st)) return { error: `${p.n}: status must be living or deceased` };
      if (p.kids != null && !Array.isArray(p.kids)) return { error: `${p.n}: grandchildren must be a list` };
      for (const g of p.kids ?? []) if (!clean(g?.id) || !clean(g?.n)) return { error: `${p.n}: every grandchild needs an id and a name` };
    }
  }
  if (!isUsableTree(next)) return { error: "Every deed holder needs a name and living/deceased" };
  const ids = new Set<string>();
  for (const list of PEOPLE_LISTS) for (const p of next[list] ?? []) {
    if (ids.has(p.id)) return { error: `Duplicate person id ${p.id}` };
    ids.add(p.id);
  }
  if (JSON.stringify(next) === JSON.stringify(cur)) return { error: "The proposed family tree is identical to the current one" };
  return { tree: next };
}

const LIST_LABEL: Record<string, string> = { deed: "On the deed", kids: "Child", sibs: "Sibling", parents: "Parent" };
const MAP_LABEL: Record<string, string> = {
  spouse: "Spouse of", heirSpouse: "Spouse of", signerSpouse: "Spouse of", will: "Left a will", poa: "Durable POA for",
  signerPoa: "Durable POA for", taker: "Takes the share of", noKids: "No children", noSibs: "No siblings", noParents: "No living parents",
};

function nameIndex(t: Json) {
  const m = new Map<string, string>();
  for (const list of PEOPLE_LISTS) for (const p of t[list] ?? []) {
    m.set(p.id, clean(p.n));
    for (const g of p.kids ?? []) m.set(g.id, clean(g.n));
  }
  return m;
}

function describePerson(p: Json, names: Map<string, string>) {
  const bits = [p.st === "deceased" ? "deceased" : p.st === "living" ? "living" : ""];
  if (Array.isArray(p.of) && p.of.length) bits.push(`of ${p.of.map((id: string) => names.get(id) ?? id).join(" & ")}`);
  if (Array.isArray(p.kids) && p.kids.length) bits.push(`children: ${p.kids.map((g: Json) => clean(g.n)).join(", ")}`);
  return bits.filter(Boolean).join(", ");
}

/** Plain-English before → after lines for the approval card. */
export function treeDiff(before: unknown, after: unknown): { label: string; before: string; after: string }[] {
  const a = (before ?? {}) as Json, b = (after ?? {}) as Json;
  const na = nameIndex(a), nb = nameIndex(b);
  const out: { label: string; before: string; after: string }[] = [];
  for (const list of PEOPLE_LISTS) {
    const old = new Map<string, Json>((a[list] ?? []).map((p: Json) => [p.id, p]));
    const neu = new Map<string, Json>((b[list] ?? []).map((p: Json) => [p.id, p]));
    for (const [id, p] of neu) {
      const o = old.get(id);
      if (!o) { out.push({ label: `${LIST_LABEL[list]} — added`, before: "(not in tree)", after: `${clean(p.n)}${describePerson(p, nb) ? ` (${describePerson(p, nb)})` : ""}` }); continue; }
      if (clean(o.n) !== clean(p.n)) out.push({ label: `${LIST_LABEL[list]} — name`, before: clean(o.n), after: clean(p.n) });
      const d0 = describePerson(o, na), d1 = describePerson(p, nb);
      if (d0 !== d1) out.push({ label: `${LIST_LABEL[list]} — ${clean(p.n)}`, before: d0 || "(blank)", after: d1 || "(blank)" });
    }
    for (const [id, o] of old) if (!neu.has(id)) out.push({ label: `${LIST_LABEL[list]} — removed`, before: clean(o.n), after: "(removed)" });
  }
  for (const k of Object.keys(MAP_LABEL)) {
    const ma = (a[k] ?? {}) as Json, mb = (b[k] ?? {}) as Json;
    for (const key of new Set([...Object.keys(ma), ...Object.keys(mb)])) {
      const s0 = JSON.stringify(ma[key] ?? null), s1 = JSON.stringify(mb[key] ?? null);
      if (s0 === s1) continue;
      const who = nb.get(key) ?? na.get(key) ?? key;
      const fmt = (v: unknown) => v == null ? "(blank)" : typeof v === "object" ? Object.entries(v as Json).filter(([, x]) => x != null && x !== "").map(([kk, x]) => `${kk === "n" ? "name" : kk === "has" ? "has" : kk}: ${x}`).join(", ") || "(blank)" : String(v);
      out.push({ label: `${MAP_LABEL[k]} ${who}`, before: fmt(ma[key]), after: fmt(mb[key]) });
    }
  }
  for (const k of ["couple", "deedRel"]) if (JSON.stringify(a[k] ?? null) !== JSON.stringify(b[k] ?? null)) out.push({ label: k === "couple" ? "Deed holders were a couple" : "Deed holders' relationship", before: String(a[k] ?? "(blank)"), after: String(b[k] ?? "(blank)") });
  return out.slice(0, 40);
}

export const LISTING_TIERS = ["starter", "pro", "featured", "set_your_price"] as const;
